import{_ as e}from"./chunks/thumb-04.CWQfosSq.js";import{_ as i}from"./chunks/photo-13.NRntnHDz.js";import{_ as t,H as r,f as o,i as n}from"./chunks/framework.Cvt1eIE0.js";const f=JSON.parse('{"title":"收藏｜工程师如何在 X 上写好技术短文","description":"","frontmatter":{"title":"收藏｜工程师如何在 X 上写好技术短文","date":"2026-05-21T00:00:00.000Z","category":"收藏","tags":["收藏","写作","X"],"excerpt":"提炼技术推特圈关于结构、证据链与「一条一个观点」的写作惯例。"},"headers":[],"relativePath":"posts/收藏/x-engineering-writing-on-social.md","filePath":"posts/收藏/x-engineering-writing-on-social.md"}'),l={name:"posts/收藏/x-engineering-writing-on-social.md"};function s(c,a,d,g,h,p){return r(),o("div",null,[...a[0]||(a[0]=[n('<img src="'+e+'" alt="配图" class="article-banner" loading="lazy"><div class="figure wide"><img src="'+i+'" alt="随拍配图" loading="lazy"><p class="figure-caption">记录本身，就是一种立场。</p></div><h1 id="工程师如何在-x-上写好技术短文" tabindex="-1">工程师如何在 X 上写好技术短文 <a class="header-anchor" href="#工程师如何在-x-上写好技术短文" aria-label="Permalink to &quot;工程师如何在 X 上写好技术短文&quot;">​</a></h1><p>技术 X（Twitter）擅长传播<strong>观点密度高</strong>的内容，但不适合替代文档。以下为社区长期沉淀的写作惯例整理。</p><h2 id="一条-一个可检验观点" tabindex="-1">一条 = 一个可检验观点 <a class="header-anchor" href="#一条-一个可检验观点" aria-label="Permalink to &quot;一条 = 一个可检验观点&quot;">​</a></h2><p>高赞帖通常只做一件事：给出结论 + 最小证据。例如：「在 Kotlin 里用 <code>supervisorScope</code> 隔离子任务失败——片段见下图」。反例：线程串里塞五个互不相关技巧。</p><h2 id="线程结构模板" tabindex="-1">线程结构模板 <a class="header-anchor" href="#线程结构模板" aria-label="Permalink to &quot;线程结构模板&quot;">​</a></h2><ol><li><strong>Hook</strong>：问题场景（「线上 OOM 排查」）</li><li><strong>转折</strong>：常见误区</li><li><strong>做法</strong>：3–5 步可执行清单</li><li><strong>收尾</strong>：邀请反驳或补充</li></ol><h2 id="证据链比语气重要" tabindex="-1">证据链比语气重要 <a class="header-anchor" href="#证据链比语气重要" aria-label="Permalink to &quot;证据链比语气重要&quot;">​</a></h2><p>社区对「玄学优化」容忍度越来越低。带 <strong>Benchmark 数字、PR 链接、官方 Issue</strong> 的帖子传播更远。没有数据时，明确标注「 anecdotal / 个人体验」反而更可信。</p><h2 id="代码截图的排版" tabindex="-1">代码截图的排版 <a class="header-anchor" href="#代码截图的排版" aria-label="Permalink to &quot;代码截图的排版&quot;">​</a></h2><ul><li>深色主题统一</li><li>裁掉无关侧边栏</li><li>关键行高亮（社区常用 redacted 风格）</li></ul><h2 id="从推文到博客" tabindex="-1">从推文到博客 <a class="header-anchor" href="#从推文到博客" aria-label="Permalink to &quot;从推文到博客&quot;">​</a></h2><p>优质 X 线程适合变博客，但要<strong>扩写上下文</strong>：前置知识、失败案例、对比方案 B。本博客「收藏」分类即承担此角色。</p><h2 id="不建议发的内容" tabindex="-1">不建议发的内容 <a class="header-anchor" href="#不建议发的内容" aria-label="Permalink to &quot;不建议发的内容&quot;">​</a></h2><ul><li>未脱敏的线上日志与用户信息</li><li>引战式「X 语言已死」</li><li>纯转发无评论的链接堆砌</li></ul><p>好技术短文像好的 commit message：<strong>让人愿意点开 diff</strong>。</p>',17)])])}const x=t(l,[["render",s]]);export{f as __pageData,x as default};
